UPDATE graph_edges
SET status = 'stale',
    updated_at = #{updatedAt}
WHERE space_id = #{spaceId}
  AND status != 'stale'
  AND (
    source_node_id IN

        #{nodeId}

    OR target_node_id IN

        #{nodeId}

  )

UPDATE graph_edges
SET status = 'stale',
    updated_at = #{updatedAt}
WHERE space_id = #{spaceId}
  AND status != 'stale'
  AND id IN (
    SELECT edge_id
    FROM evidences
    WHERE space_id = #{spaceId}
      AND source_document_id = #{documentId}
  )
  AND NOT EXISTS (
    SELECT 1
    FROM evidences active_evidence
    INNER JOIN source_documents active_document
            ON active_document.id = active_evidence.source_document_id
    WHERE active_evidence.edge_id = graph_edges.id
      AND active_evidence.space_id = #{spaceId}
      AND active_document.status = 'active'
  )
